-- Product reference layer. Naming center remains the master; no legacy product table is altered.
CREATE TABLE IF NOT EXISTS cc_commercial_products (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, source_product_id BIGINT UNSIGNED NOT NULL, model VARCHAR(120) NOT NULL, series VARCHAR(120) NULL, category VARCHAR(120) NULL, product_name VARCHAR(190) NULL, image VARCHAR(500) NULL, dimension_image VARCHAR(500) NULL, status VARCHAR(40) NOT NULL DEFAULT 'draft', source_updated_at DATETIME NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_product_source(source_product_id), UNIQUE KEY uq_cc_product_model(model), KEY idx_cc_product_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_product_sync_logs (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, sync_at DATETIME NOT NULL, triggered_by_legacy_user_id INT UNSIGNED NULL, total_count INT UNSIGNED NOT NULL DEFAULT 0, success_count INT UNSIGNED NOT NULL DEFAULT 0, failed_count INT UNSIGNED NOT NULL DEFAULT 0, error_message VARCHAR(1000) NULL, status VARCHAR(30) NOT NULL DEFAULT 'not_configured', created_at DATETIME NOT NULL, PRIMARY KEY(id), KEY idx_cc_product_sync_time(sync_at,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cc_product_options (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, product_id BIGINT UNSIGNED NOT NULL, option_name VARCHAR(120) NOT NULL, option_value VARCHAR(190) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_cc_product_option(product_id,option_name,option_value), KEY idx_cc_product_option_status(product_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
